401	\begin{lemma}[Collision of two linear forms in the combining variables]
402		\label{lem:ld-combining-collision}
403		\lean{MIPStarRE.QPBT.combiningLinearForm}
404		\lean{MIPStarRE.QPBT.combiningLinearForm_injective}
