409		Let $c, b \in \F_q^k$ with $c \neq b$.  Then
410		\[
411			\Pr_{\alpha \in \F_q^k}\Bigl[\; \sum_{r} c_r \alpha_r
412				= \sum_{r} b_r \alpha_r \;\Bigr] \;\le\; \frac1q\;,
413		\]
414		the probability being over a uniformly random $\alpha$.
415	\end{lemma}
416	\begin{proof}
417		\leanok
418		\uses{lem:schwartz-zippel-total-degree}
419		The two sides are the evaluations at $\alpha$ of the linear forms
420		$\sum_r c_r X_r$ and $\sum_r b_r X_r$ in $k$ variables.  The coefficient of
421		$X_r$ in such a form is $c_r$, so the two forms are distinct polynomials,
422		and each has total degree at most $1$.  Lemma~\ref{lem:schwartz-zippel-total-degree}
423		bounds the probability that two distinct polynomials of total degree at most
424		$1$ agree at a uniformly random point of $\F_q^k$ by $1/q$.
425	\end{proof}
